DROP FUNCTION public.request_invoice_refund(uuid,text); DROP FUNCTION public.review_invoice_refund(uuid,text,text);
CREATE FUNCTION public.request_invoice_refund(actor uuid, invoice uuid, explanation text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE inv public.billing_invoices; request_id uuid; BEGIN IF actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF; SELECT * INTO inv FROM public.billing_invoices WHERE id=invoice AND user_id=actor FOR UPDATE; IF inv.id IS NULL OR inv.status<>'paid' OR inv.environment<>'live' OR inv.amount_paid_minor<=inv.amount_refunded_minor THEN RAISE EXCEPTION 'Invoice is not eligible'; END IF; INSERT INTO public.refund_requests(invoice_id,user_id,reason) VALUES(inv.id,actor,btrim(explanation)) RETURNING id INTO request_id; RETURN request_id; END $$;
REVOKE ALL ON FUNCTION public.request_invoice_refund(uuid,uuid,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.request_invoice_refund(uuid,uuid,text) TO service_role;
CREATE FUNCTION public.review_invoice_refund(actor uuid, request uuid, decision text, note text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(actor,'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; IF decision NOT IN ('approved_pending_provider','rejected') OR length(btrim(note)) NOT BETWEEN 3 AND 2000 THEN RAISE EXCEPTION 'Invalid review'; END IF; UPDATE public.refund_requests SET status=decision,review_note=btrim(note),reviewed_by=actor,reviewed_at=now() WHERE id=request AND status='pending'; IF NOT FOUND THEN RAISE EXCEPTION 'Request already reviewed or missing'; END IF; END $$;
REVOKE ALL ON FUNCTION public.review_invoice_refund(uuid,uuid,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.review_invoice_refund(uuid,uuid,text,text) TO service_role;